From 1ed3505590c25687cf86274407507a51d1d16e11 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:09:17 +0100
Subject: [PATCH] activitymanager: show Picture of the Day and slideshow
 wallpapers

Activity tiles only knew how to read image and color wallpapers, so an
activity using Picture of the Day or a slideshow kept a stale or empty
tile. Use the slideshow's saved slide and the cached picture of the day.

BUG: 449823
---
 .../activitymanager/sortedactivitiesmodel.cpp  | 18 +++++++++++++++---
 1 file changed, 15 insertions(+), 3 deletions(-)

diff --git a/imports/activitymanager/sortedactivitiesmodel.cpp b/imports/activitymanager/sortedactivitiesmodel.cpp
index f200d0655d..760bcfdb32 100644
--- a/imports/activitymanager/sortedactivitiesmodel.cpp
+++ b/imports/activitymanager/sortedactivitiesmodel.cpp
@@ -135,14 +135,16 @@ public:
         auto wallpaperPlugin = config.readEntry("wallpaperplugin");
         auto wallpaperConfig = config.group(QStringLiteral("Wallpaper")).group(wallpaperPlugin).group(QStringLiteral("General"));

-        if (wallpaperPlugin == u"org.kde.image") {
+        if (wallpaperPlugin == u"org.kde.image" || wallpaperPlugin == u"org.kde.slideshow") {
             // we can have three cases:
             // - Image is a URL to a specific image -> use that
             // - Image is a URL to a wallpaper package folder -> pick one image from that folder
             // - Image is empty -> use default wallpaper
+            // The slideshow stores its current slide in Image as well.

-            const QUrl defaultWallpaper =
-                QUrl::fromLocalFile(QStandardPaths::locate(QStandardPaths::GenericDataLocation, u"wallpapers/Next"_s, QStandardPaths::LocateDirectory));
+            const QUrl defaultWallpaper = wallpaperPlugin == u"org.kde.image"
+                ? QUrl::fromLocalFile(QStandardPaths::locate(QStandardPaths::GenericDataLocation, u"wallpapers/Next"_s, QStandardPaths::LocateDirectory))
+                : QUrl();

             const QUrl wallpaper = wallpaperConfig.readEntry("Image", defaultWallpaper);

@@ -154,6 +156,16 @@ public:
         } else if (wallpaperPlugin == u"org.kde.color") {
             auto backgroundColor = wallpaperConfig.readEntry("Color", QColor(29, 153, 243));
             return backgroundColor.name();
+        } else if (wallpaperPlugin == u"org.kde.potd") {
+            // Picture of the Day caches the current image as <provider>[:<args>]
+            const QString provider = wallpaperConfig.readEntry("Provider", u"apod"_s);
+            const QDir cacheDir(QStandardPaths::writableLocation(QStandardPaths::GenericCacheLocation) + u"/plasma_engine_potd"_s);
+            const auto files = cacheDir.entryInfoList({provider, provider + u":*"_s}, QDir::Files, QDir::Time);
+            for (const QFileInfo &file : files) {
+                if (file.suffix() != u"json") {
+                    return QUrl::fromLocalFile(file.absoluteFilePath()).toString();
+                }
+            }
         }

         return QString();
-- 
